function fFt(n) {
	const t = [];
	for (let e = 0; e < n.length; e++) {
		const r = n[e];
		let i = 0;
		for (; i < r.length; ) {
			const s = r[i];
			if (s === "." || s === " ") {
				i++;
				continue;
			}
			const a = i;
			for (; i < r.length && r[i] !== "." && r[i] !== " "; ) i++;
			t.push({ x: a, y: e, w: i - a });
		}
	}
	return t;
}
